#!/usr/bin/env python3
"""Generate crates/pgarbor-catalog/src/builtin/ext_rows.rs from contracts/reference/pg18
(pg_amop.csv, pg_amproc.csv, pg_conversion.csv), dumped from the pinned PostgreSQL 18.6 oracle."""
import csv, os
ROOT = os.path.dirname(os.path.abspath(__file__)) + '/../../..'
REF = ROOT + '/contracts/reference/pg18/'
out = ['// @generated by crates/pgarbor-catalog/gen/gen_ext_rows.py from contracts/reference/pg18 (PostgreSQL 18.6).',
       '// DO NOT EDIT BY HAND.',
       '//! Builtin `pg_amop`, `pg_amproc` and `pg_conversion` rows (amendment pgarbor-catalog-09).',
       'use pgarbor_common::Oid;', '',
       '/// `pg_amop`: (oid, family, lefttype, righttype, strategy, purpose, operator, method, sortfamily).',
       'pub static AMOPS: &[(Oid, Oid, Oid, Oid, i16, u8, Oid, Oid, Oid)] = &[']
for r in csv.DictReader(open(REF + 'pg_amop.csv')):
    out.append(f"    ({r['oid']}, {r['amopfamily']}, {r['amoplefttype']}, {r['amoprighttype']}, {r['amopstrategy']}, b'{r['amoppurpose']}', {r['amopopr']}, {r['amopmethod']}, {r['amopsortfamily']}),")
out += ['];', '', '/// `pg_amproc`: (oid, family, lefttype, righttype, procnum, proc).',
        'pub static AMPROCS: &[(Oid, Oid, Oid, Oid, i16, Oid)] = &[']
for r in csv.DictReader(open(REF + 'pg_amproc.csv')):
    out.append(f"    ({r['oid']}, {r['amprocfamily']}, {r['amproclefttype']}, {r['amprocrighttype']}, {r['amprocnum']}, {r['amproc']}),")
out += ['];', '', '/// `pg_conversion`: (oid, name, for_encoding, to_encoding, proc, is_default); namespace 11, owner 10.',
        'pub static CONVERSIONS: &[(Oid, &str, i32, i32, Oid, bool)] = &[']
for r in csv.DictReader(open(REF + 'pg_conversion.csv')):
    out.append(f"    ({r['oid']}, \"{r['conname']}\", {r['conforencoding']}, {r['contoencoding']}, {r['conproc']}, {'true' if r['condefault']=='t' else 'false'}),")
out += ['];', '']
open(ROOT + '/crates/pgarbor-catalog/src/builtin/ext_rows.rs', 'w').write('\n'.join(out))
